/* ===== Design Tokens ===== */
:root {
  --color-brand:        #1a1a2e;
  --color-brand-mid:    #16213e;
  --color-accent:       #e94560;
  --color-accent-dark:  #c73652;
  --color-surface:      #ffffff;
  --color-surface-alt:  #f6f7f9;
  --color-border:       #e2e4e9;
  --color-text-primary: #0f0f1a;
  --color-text-muted:   #6b7280;
  --color-text-inverse: #ffffff;
  --color-badge-sale:   #e94560;
  --color-badge-new:    #059669;
  --color-focus:        #1a6ef7;

  --radius-sm:  4px;
  --radius-md:  8px;
  --radius-lg:  16px;
  --radius-xl:  24px;
  --radius-full: 9999px;

  --shadow-sm:  0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.04);
  --shadow-md:  0 4px 12px rgba(0,0,0,.10), 0 2px 4px rgba(0,0,0,.06);
  --shadow-lg:  0 10px 30px rgba(0,0,0,.12), 0 4px 8px rgba(0,0,0,.06);

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Inter', system-ui, -apple-system, sans-serif;

  --transition: 200ms cubic-bezier(.4,0,.2,1);
}

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  color: var(--color-text-primary);
  background: var(--color-surface);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font: inherit; border: none; background: none; }
ul, ol { list-style: none; }

/* ===== Focus ===== */
:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ===== Skip Link ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: .5rem 1rem;
  background: var(--color-focus);
  color: #fff;
  border-radius: var(--radius-md);
  font-weight: 600;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ===== Layout helpers ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2rem);
}

/* ===== Announcement Bar ===== */
.announcement-bar {
  background: var(--color-brand);
  color: var(--color-text-inverse);
  text-align: center;
  padding: .5rem 1rem;
  font-size: .8125rem;
  letter-spacing: .03em;
}
.announcement-bar a {
  color: var(--color-accent);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.announcement-bar a:hover { color: #ff7a90; }

/* ===== Header ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
  padding-block: .875rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--color-brand);
  letter-spacing: -.02em;
  white-space: nowrap;
}
.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
}
.logo-icon svg { fill: #fff; }

/* Nav */
.primary-nav { display: flex; justify-content: center; }
.nav-list {
  display: flex;
  gap: .25rem;
  align-items: center;
}
.nav-link {
  display: inline-block;
  padding: .375rem .75rem;
  border-radius: var(--radius-full);
  font-size: .9375rem;
  font-weight: 500;
  color: var(--color-text-primary);
  transition: background var(--transition), color var(--transition);
}
.nav-link:hover, .nav-link[aria-current="page"] {
  background: var(--color-surface-alt);
  color: var(--color-accent);
}

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
}

.icon-btn {
  position: relative;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  color: var(--color-text-primary);
  transition: background var(--transition);
}
.icon-btn:hover { background: var(--color-surface-alt); }
.icon-btn svg { width: 22px; height: 22px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px; height: 18px;
  background: var(--color-accent);
  color: #fff;
  font-size: .625rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  display: grid;
  place-items: center;
  padding-inline: 4px;
  line-height: 1;
  border: 2px solid var(--color-surface);
}

.search-form {
  display: flex;
  align-items: center;
  background: var(--color-surface-alt);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: .375rem .75rem;
  gap: .5rem;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.search-form:focus-within {
  border-color: var(--color-focus);
  box-shadow: 0 0 0 3px rgba(26,110,247,.15);
}
.search-form svg { width: 18px; height: 18px; stroke: var(--color-text-muted); fill: none; stroke-width: 2; flex-shrink: 0; }
.search-input {
  border: none;
  background: transparent;
  font-size: .9rem;
  color: var(--color-text-primary);
  width: 200px;
  outline: none;
}
.search-input::placeholder { color: var(--color-text-muted); }

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  width: 40px; height: 40px;
  border-radius: var(--radius-md);
  align-items: center;
  justify-content: center;
  color: var(--color-text-primary);
  transition: background var(--transition);
}
.menu-toggle:hover { background: var(--color-surface-alt); }
.menu-toggle svg { width: 24px; height: 24px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; }

/* ===== Hero ===== */
.hero {
  background: linear-gradient(135deg, var(--color-brand) 0%, #0f3460 60%, #533483 100%);
  color: var(--color-text-inverse);
  overflow: hidden;
  position: relative;
}
.hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E") repeat;
  pointer-events: none;
}

.hero-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
  padding-block: clamp(3rem, 8vw, 6rem);
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: rgba(233,69,96,.2);
  border: 1px solid rgba(233,69,96,.4);
  color: #ff8fa3;
  font-size: .8125rem;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: .3rem .75rem;
  border-radius: var(--radius-full);
  margin-bottom: 1.25rem;
}
.hero-eyebrow-dot { width: 6px; height: 6px; background: var(--color-accent); border-radius: 50%; }

.hero-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1.25rem;
}
.hero-title em {
  font-style: normal;
  color: var(--color-accent);
  display: block;
}

.hero-desc {
  font-size: 1.0625rem;
  color: rgba(255,255,255,.75);
  margin-bottom: 2rem;
  max-width: 44ch;
  line-height: 1.7;
}

.hero-cta-group {
  display: flex;
  gap: .75rem;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.5rem;
  border-radius: var(--radius-full);
  font-size: .9375rem;
  font-weight: 600;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn svg { width: 18px; height: 18px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

.btn-primary {
  background: var(--color-accent);
  color: #fff;
}
.btn-primary:hover { background: var(--color-accent-dark); transform: translateY(-1px); box-shadow: 0 6px 20px rgba(233,69,96,.4); }

.btn-outline {
  background: transparent;
  color: #fff;
  border: 1.5px solid rgba(255,255,255,.4);
}
.btn-outline:hover { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.7); }

.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 2.5rem;
}
.stat-item { display: flex; flex-direction: column; }
.stat-value { font-size: 1.5rem; font-weight: 800; letter-spacing: -.02em; }
.stat-label { font-size: .8125rem; color: rgba(255,255,255,.6); }

/* Hero visual */
.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}
.hero-card-stack {
  position: relative;
  width: 320px;
  height: 380px;
}
.hero-product-card {
  position: absolute;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
.hero-product-card.card-main {
  width: 240px; height: 300px;
  top: 40px; left: 40px;
  background: linear-gradient(145deg, #fff5f7, #ffeef2);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: .75rem;
  z-index: 2;
}
.hero-product-card.card-bg {
  width: 200px; height: 260px;
  top: 20px; left: 80px;
  background: linear-gradient(145deg, #e8edf8, #d4ddf5);
  z-index: 1;
  transform: rotate(6deg);
}
.hero-product-card.card-accent {
  width: 160px; height: 200px;
  top: 100px; left: 10px;
  background: linear-gradient(145deg, #fff3e0, #ffe0b2);
  z-index: 3;
  transform: rotate(-8deg);
}
.product-card-emoji { font-size: 4rem; line-height: 1; }
.product-card-label { font-size: .875rem; font-weight: 600; color: var(--color-text-primary); }

/* Floating badge */
.hero-float-badge {
  position: absolute;
  bottom: 30px; right: 0;
  background: #fff;
  border-radius: var(--radius-lg);
  padding: .75rem 1rem;
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  gap: .625rem;
  z-index: 4;
}
.float-badge-icon { font-size: 1.25rem; }
.float-badge-text { display: flex; flex-direction: column; }
.float-badge-primary { font-size: .875rem; font-weight: 700; color: var(--color-text-primary); }
.float-badge-secondary { font-size: .75rem; color: var(--color-text-muted); }

/* ===== Section common ===== */
.section { padding-block: clamp(2.5rem, 6vw, 5rem); }
.section-alt { background: var(--color-surface-alt); }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.section-eyebrow {
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: .375rem;
}

.section-title {
  font-size: clamp(1.375rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.2;
}

.section-link {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  font-size: .9375rem;
  font-weight: 600;
  color: var(--color-accent);
  white-space: nowrap;
  transition: gap var(--transition);
}
.section-link:hover { gap: .625rem; }
.section-link svg { width: 18px; height: 18px; stroke: currentColor; fill: none; stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }

/* ===== Categories ===== */
.categories-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: .75rem;
}

.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .625rem;
  padding: 1.25rem .75rem;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-lg);
  text-align: center;
  cursor: pointer;
  transition: all var(--transition);
}
.category-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.category-card:hover .category-icon { background: var(--color-accent); color: #fff; }

.category-icon {
  width: 52px; height: 52px;
  background: var(--color-surface-alt);
  border-radius: var(--radius-md);
  display: grid;
  place-items: center;
  font-size: 1.625rem;
  transition: background var(--transition), color var(--transition);
}

.category-name {
  font-size: .8125rem;
  font-weight: 600;
  color: var(--color-text-primary);
  line-height: 1.3;
}

.category-count {
  font-size: .75rem;
  color: var(--color-text-muted);
}

/* ===== Product Grid ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

/* Product Card */
.product-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1.5px solid var(--color-border);
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  border-color: transparent;
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.product-card-image {
  position: relative;
  aspect-ratio: 1;
  background: var(--color-surface-alt);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
}

.product-badges {
  position: absolute;
  top: .75rem; left: .75rem;
  display: flex;
  flex-direction: column;
  gap: .375rem;
}

.badge {
  display: inline-block;
  padding: .2rem .6rem;
  border-radius: var(--radius-full);
  font-size: .6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
}
.badge-sale { background: var(--color-badge-sale); color: #fff; }
.badge-new  { background: var(--color-badge-new);  color: #fff; }
.badge-hot  { background: #f59e0b; color: #fff; }

.product-actions {
  position: absolute;
  top: .75rem; right: .75rem;
  display: flex;
  flex-direction: column;
  gap: .375rem;
  opacity: 0;
  transform: translateX(8px);
  transition: all var(--transition);
}
.product-card:hover .product-actions,
.product-card:focus-within .product-actions { opacity: 1; transform: translateX(0); }

.action-btn {
  width: 36px; height: 36px;
  background: var(--color-surface);
  border-radius: var(--radius-full);
  display: grid;
  place-items: center;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  color: var(--color-text-primary);
}
.action-btn:hover { background: var(--color-accent); color: #fff; }
.action-btn svg { width: 17px; height: 17px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

.product-card-body {
  padding: 1rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: .375rem;
}

.product-brand {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.product-name {
  font-size: .9375rem;
  font-weight: 600;
  color: var(--color-text-primary);
  line-height: 1.4;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .375rem;
}
.stars {
  display: flex;
  gap: 1px;
}
.star { width: 14px; height: 14px; fill: #f59e0b; }
.star-empty { fill: var(--color-border); }
.rating-count { font-size: .75rem; color: var(--color-text-muted); }

.product-price-row {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-top: auto;
  padding-top: .5rem;
}
.price-current {
  font-size: 1.125rem;
  font-weight: 800;
  color: var(--color-text-primary);
}
.price-original {
  font-size: .875rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
}
.price-discount {
  font-size: .75rem;
  font-weight: 700;
  color: var(--color-badge-sale);
}

.add-to-cart-btn {
  width: 100%;
  margin-top: .75rem;
  padding: .625rem;
  background: var(--color-brand);
  color: #fff;
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  transition: all var(--transition);
}
.add-to-cart-btn:hover { background: var(--color-accent); transform: translateY(-1px); }
.add-to-cart-btn svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }

/* ===== Deals / Countdown ===== */
.deals-section { background: linear-gradient(135deg, #0f0f1a 0%, #1a1a2e 100%); color: #fff; }

.deals-header .section-title { color: #fff; }

.countdown-wrapper {
  display: flex;
  align-items: center;
  gap: .5rem;
}
.countdown-label { font-size: .875rem; color: rgba(255,255,255,.6); }
.countdown-timer {
  display: flex;
  align-items: center;
  gap: .25rem;
}
.time-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(255,255,255,.1);
  border-radius: var(--radius-sm);
  padding: .375rem .625rem;
  min-width: 44px;
}
.time-value {
  font-size: 1.25rem;
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.time-label { font-size: .625rem; color: rgba(255,255,255,.5); text-transform: uppercase; letter-spacing: .06em; }
.time-colon { font-size: 1.25rem; font-weight: 700; color: rgba(255,255,255,.4); padding-bottom: .5rem; }

.deals-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

.deal-card {
  background: rgba(255,255,255,.05);
  border: 1.5px solid rgba(255,255,255,.1);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition);
}
.deal-card:hover { border-color: var(--color-accent); background: rgba(255,255,255,.08); transform: translateY(-3px); }

.deal-card-image {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  position: relative;
  background: rgba(255,255,255,.04);
}

.deal-discount-circle {
  position: absolute;
  top: .75rem; right: .75rem;
  width: 52px; height: 52px;
  background: var(--color-accent);
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: .75rem;
  font-weight: 800;
  line-height: 1.1;
  text-align: center;
}

.deal-card-body { padding: 1rem; }
.deal-name {
  font-size: .9375rem;
  font-weight: 600;
  color: #fff;
  margin-bottom: .375rem;
}

.deal-price-row {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-bottom: .75rem;
}
.deal-price-current { font-size: 1.25rem; font-weight: 800; color: var(--color-accent); }
.deal-price-original { font-size: .875rem; color: rgba(255,255,255,.4); text-decoration: line-through; }

.deal-progress { margin-bottom: .375rem; }
.progress-bar {
  height: 4px;
  background: rgba(255,255,255,.12);
  border-radius: var(--radius-full);
  overflow: hidden;
}
.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--color-accent), #ff8fa3);
  border-radius: var(--radius-full);
  transition: width 1s ease;
}
.progress-label { font-size: .75rem; color: rgba(255,255,255,.5); margin-top: .25rem; }

.deal-btn {
  width: 100%;
  padding: .625rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 600;
  text-align: center;
  transition: all var(--transition);
}
.deal-btn:hover { background: var(--color-accent-dark); transform: translateY(-1px); }

/* ===== Trending / Tabs ===== */
.tabs-nav {
  display: flex;
  gap: .5rem;
  border-bottom: 1.5px solid var(--color-border);
  margin-bottom: 2rem;
}
.tab-btn {
  padding: .625rem 1.25rem;
  font-size: .9375rem;
  font-weight: 600;
  color: var(--color-text-muted);
  border-radius: var(--radius-md) var(--radius-md) 0 0;
  border-bottom: 2px solid transparent;
  margin-bottom: -1.5px;
  transition: all var(--transition);
}
.tab-btn:hover { color: var(--color-text-primary); background: var(--color-surface-alt); }
.tab-btn[aria-selected="true"] {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
  background: transparent;
}

.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ===== Editorial / Blog ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.5rem;
}

.editorial-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  display: flex;
  flex-direction: column;
  transition: all var(--transition);
}
.editorial-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); border-color: transparent; }

.editorial-card.featured {
  grid-column: span 2;
  flex-direction: row;
}

.editorial-image {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  font-size: 5rem;
}
.editorial-card:not(.featured) .editorial-image {
  aspect-ratio: 16/9;
}
.editorial-card.featured .editorial-image {
  width: 45%;
  font-size: 8rem;
}

.editorial-body {
  padding: 1.5rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: .625rem;
}

.editorial-tag {
  display: inline-block;
  padding: .2rem .625rem;
  background: rgba(233,69,96,.1);
  color: var(--color-accent);
  border-radius: var(--radius-full);
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
  align-self: flex-start;
}

.editorial-title {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--color-text-primary);
  line-height: 1.4;
}
.editorial-card.featured .editorial-title { font-size: 1.375rem; }

.editorial-excerpt {
  font-size: .875rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  flex: 1;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: .75rem;
  font-size: .8125rem;
  color: var(--color-text-muted);
  margin-top: auto;
  padding-top: .5rem;
}
.editorial-meta-dot { width: 3px; height: 3px; background: var(--color-border); border-radius: 50%; }

.read-more-link {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  margin-top: .25rem;
  transition: gap var(--transition);
}
.read-more-link:hover { gap: .625rem; }
.read-more-link svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }

/* ===== Banner / Promo Strip ===== */
.promo-strip {
  background: linear-gradient(135deg, var(--color-accent) 0%, #c0392b 100%);
  padding-block: 2.5rem;
}
.promo-strip-inner {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 2rem;
}
.promo-strip-text h2 { font-size: clamp(1.25rem, 3vw, 1.875rem); font-weight: 800; color: #fff; margin-bottom: .375rem; }
.promo-strip-text p { color: rgba(255,255,255,.8); font-size: .9375rem; }
.btn-white {
  background: #fff;
  color: var(--color-accent);
  font-weight: 700;
  padding: .75rem 2rem;
  border-radius: var(--radius-full);
  white-space: nowrap;
  transition: all var(--transition);
  display: inline-flex;
  align-items: center;
  gap: .5rem;
}
.btn-white:hover { background: #fff; transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,.2); }
.btn-white svg { width: 18px; height: 18px; stroke: currentColor; fill: none; stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }

/* ===== Trust Badges ===== */
.trust-bar {
  border-top: 1.5px solid var(--color-border);
  border-bottom: 1.5px solid var(--color-border);
  padding-block: 1.5rem;
}
.trust-list {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  text-align: center;
}
.trust-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .5rem;
}
.trust-icon { font-size: 1.75rem; }
.trust-title { font-size: .9375rem; font-weight: 700; }
.trust-desc { font-size: .8125rem; color: var(--color-text-muted); }

/* ===== Newsletter ===== */
.newsletter-section {
  background: var(--color-surface-alt);
  padding-block: clamp(2.5rem, 5vw, 4rem);
}
.newsletter-inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}
.newsletter-inner .section-eyebrow { margin-bottom: .5rem; }
.newsletter-inner .section-title { margin-bottom: .75rem; }
.newsletter-desc {
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
  font-size: .9375rem;
}
.newsletter-form {
  display: flex;
  gap: .5rem;
  max-width: 440px;
  margin-inline: auto;
}
.newsletter-input {
  flex: 1;
  padding: .75rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: .9375rem;
  background: var(--color-surface);
  color: var(--color-text-primary);
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-input:focus { border-color: var(--color-focus); }
.newsletter-input::placeholder { color: var(--color-text-muted); }
.newsletter-disclaimer { font-size: .75rem; color: var(--color-text-muted); margin-top: .75rem; }

/* ===== Footer ===== */
.site-footer {
  background: var(--color-brand);
  color: rgba(255,255,255,.8);
}
.footer-top {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 2.5rem;
  padding-block: 3rem;
}

.footer-brand .logo { color: #fff; margin-bottom: .75rem; }
.footer-tagline { font-size: .9rem; color: rgba(255,255,255,.55); line-height: 1.7; max-width: 28ch; }

.footer-social { display: flex; gap: .625rem; margin-top: 1.25rem; }
.social-link {
  width: 36px; height: 36px;
  background: rgba(255,255,255,.1);
  border-radius: var(--radius-md);
  display: grid;
  place-items: center;
  transition: background var(--transition);
}
.social-link:hover { background: var(--color-accent); }
.social-link svg { width: 18px; height: 18px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

.footer-col-title {
  font-size: .875rem;
  font-weight: 700;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: 1rem;
}
.footer-links { display: flex; flex-direction: column; gap: .5rem; }
.footer-link {
  font-size: .9rem;
  color: rgba(255,255,255,.55);
  transition: color var(--transition);
}
.footer-link:hover { color: #fff; }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-block: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.footer-copy { font-size: .8125rem; color: rgba(255,255,255,.4); }
.footer-legal { display: flex; gap: 1.25rem; }
.footer-legal a { font-size: .8125rem; color: rgba(255,255,255,.4); transition: color var(--transition); }
.footer-legal a:hover { color: rgba(255,255,255,.8); }

/* ===== Cart Notification ===== */
.cart-notification {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  background: var(--color-brand);
  color: #fff;
  padding: 1rem 1.25rem;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: .75rem;
  z-index: 200;
  transform: translateY(120%);
  transition: transform var(--transition);
  max-width: 320px;
}
.cart-notification.show { transform: translateY(0); }
.cart-notification-icon { font-size: 1.25rem; flex-shrink: 0; }
.cart-notification-text { font-size: .9rem; font-weight: 500; }
.cart-notification-close {
  margin-left: auto;
  color: rgba(255,255,255,.6);
  font-size: 1.25rem;
  line-height: 1;
  flex-shrink: 0;
  transition: color var(--transition);
}
.cart-notification-close:hover { color: #fff; }

/* ===== Responsive ===== */
@media (max-width: 1100px) {
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .products-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 900px) {
  .hero-inner { grid-template-columns: 1fr; text-align: center; }
  .hero-desc { margin-inline: auto; }
  .hero-cta-group { justify-content: center; }
  .hero-stats { justify-content: center; }
  .hero-visual { display: none; }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card.featured { grid-column: span 2; }
}

@media (max-width: 700px) {
  .header-inner { grid-template-columns: auto auto; }
  .primary-nav { display: none; }
  .search-form { display: none; }
  .menu-toggle { display: flex; }

  .primary-nav.open {
    display: flex;
    position: fixed;
    inset: 0;
    top: 0;
    background: var(--color-surface);
    flex-direction: column;
    justify-content: center;
    align-items: center;
    z-index: 99;
  }
  .primary-nav.open .nav-list { flex-direction: column; gap: .5rem; font-size: 1.25rem; }
  .primary-nav.open .nav-link { font-size: 1.25rem; padding: .75rem 2rem; }
  .menu-close { display: none; }
  .primary-nav.open .menu-close { display: flex; position: absolute; top: 1rem; right: 1rem; }

  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .trust-list { grid-template-columns: repeat(2, 1fr); }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card.featured { grid-column: 1; flex-direction: column; }
  .editorial-card.featured .editorial-image { width: 100%; font-size: 5rem; aspect-ratio: 16/9; }
  .promo-strip-inner { grid-template-columns: 1fr; text-align: center; justify-items: center; }
  .footer-top { grid-template-columns: 1fr; }
  .newsletter-form { flex-direction: column; }
}

@media (max-width: 480px) {
  .products-grid { grid-template-columns: 1fr 1fr; gap: .75rem; }
  .deals-grid { grid-template-columns: 1fr 1fr; gap: .75rem; }
  .footer-bottom { flex-direction: column; text-align: center; }
}

/* ===== Forced Colors ===== */
@media (forced-colors: active) {
  .btn-primary, .add-to-cart-btn, .deal-btn, .btn-white {
    background: ButtonText;
    color: ButtonFace;
    border: 1px solid ButtonBorder;
    forced-color-adjust: none;
  }
  .badge { border: 1px solid ButtonBorder; }
  .card-notification, .cart-badge { border: 1px solid ButtonBorder; }
  .progress-fill { background: Highlight; }
  .logo-icon { background: ButtonText; forced-color-adjust: none; }
  :focus-visible { outline: 3px solid Highlight; }
}

/* ===== Reduced Motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    transition-duration: .01ms !important;
  }
  html { scroll-behavior: auto; }
}

