+}
+
+.product-card-image {
+  position: relative;
+  aspect-ratio: 1;
+  background: var(--color-surface-alt);
+  overflow: hidden;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 5rem;
+}
+
+.product-badges {
+  position: absolute;
+  top: .75rem; left: .75rem;
+  display: flex;
+  flex-direction: column;
+  gap: .375rem;
+}
+
+.badge {
+  display: inline-block;
+  padding: .2rem .6rem;
