+  font-weight: 800;
+  line-height: 1.1;
+  text-align: center;
+}
+
+.deal-card-body { padding: 1rem; }
+.deal-name {
+  font-size: .9375rem;
+  font-weight: 600;
+  color: #fff;
+  margin-bottom: .375rem;
+}
+
+.deal-price-row {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  margin-bottom: .75rem;
+}
+.deal-price-current { font-size: 1.25rem; font-weight: 800; color: var(--color-accent); }
+.deal-price-original { font-size: .875rem; color: rgba(255,255,255,.4); text-decoration: line-through; }
