+  btns.forEach((btn, i) => {
+    btn.addEventListener('click', () => activateTab(i));
+    btn.addEventListener('keydown', (e) => {
+      if (e.key === 'ArrowRight') { e.preventDefault(); activateTab((i + 1) % btns.length); btns[(i + 1) % btns.length].focus(); }
+      if (e.key === 'ArrowLeft')  { e.preventDefault(); activateTab((i - 1 + btns.length) % btns.length); btns[(i - 1 + btns.length) % btns.length].focus(); }
+      if (e.key === 'Home')       { e.preventDefault(); activateTab(0); btns[0].focus(); }
+      if (e.key === 'End')        { e.preventDefault(); activateTab(btns.length - 1); btns[btns.length - 1].focus(); }
