      <div class="product-price-row">
        <span class="price-current">${formatPrice(product.price)}</span>
        ${product.original ? `<span class="price-original" aria-label="Original price ${formatPrice(product.original)}">${formatPrice(product.original)}</span>` : ''}
        ${product.discount ? `<span class="price-discount" aria-label="${product.discount} off">${product.discount} off</span>` : ''}
      </div>
      <button class="add-to-cart-btn" data-id="${product.id}" aria-label="Add ${product.name} to cart">
        ${cartIcon()} Add to Cart
      </button>
    </div>
  </article>`;
}

// ── Component: DealCard ──────────────────────────────
function DealCard(deal) {
  const pct = Math.round((deal.sold / deal.total) * 100);
  return `
  <article class="deal-card">
    <div class="deal-card-image" role="img" aria-label="${deal.name} product image">
      <span aria-hidden="true">${deal.emoji}</span>
      <div class="deal-discount-circle" aria-hidden="true">${deal.discount}<br>OFF</div>
    </div>
    <div class="deal-card-body">
      <h3 class="deal-name">${deal.name}</h3>
      <div class="deal-price-row">
        <span class="deal-price-current">${formatPrice(deal.price)}</span>
        <span class="deal-price-original" aria-label="Original price ${formatPrice(deal.original)}">${formatPrice(deal.original)}</span>
      </div>
      <div class="deal-progress">
        <div class="progress-bar" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100" aria-label="${deal.sold} of ${deal.total} sold">
          <div class="progress-fill" style="width:${pct}%"></div>
        </div>
        <p class="progress-label">${deal.sold} sold of ${deal.total} available</p>
      </div>
      <button class="deal-btn" data-deal-id="${deal.id}" aria-label="Grab deal: ${deal.name} at ${formatPrice(deal.price)}">
        Grab This Deal
      </button>
    </div>
  </article>`;
}

// ── Component: CategoryCard ──────────────────────────
function CategoryCard(cat) {
  return `
  <a href="#" class="category-card" aria-label="${cat.name} – ${cat.count} products">
    <div class="category-icon" aria-hidden="true">${cat.emoji}</div>
    <span class="category-name">${cat.name}</span>
    <span class="category-count">${cat.count} items</span>
  </a>`;
}

// ── Component: EditorialCard ─────────────────────────
function EditorialCard(item) {
  const classes = ['editorial-card', item.featured ? 'featured' : ''].filter(Boolean).join(' ');
  const imgStyle = `background:${item.gradient};`;
  return `
  <article class="${classes}">
    <div class="editorial-image" style="${imgStyle}" role="img" aria-label="${item.title} article illustration">
      <span aria-hidden="true">${item.emoji}</span>
    </div>
    <div class="editorial-body">
      <span class="editorial-tag">${item.tag}</span>
      <h3 class="editorial-title">${item.title}</h3>
      <p class="editorial-excerpt">${item.excerpt}</p>
      <div class="editorial-meta">
        <span>${item.date}</span>
        <span class="editorial-meta-dot" aria-hidden="true"></span>
        <span>${item.readTime}</span>
      </div>
      <a href="#" class="read-more-link">
        Read Article ${chevronRight()}
      </a>
    </div>
  </article>`;
}

// ── Component: CartNotification ───────────────────────
function showCartNotification(name) {
  const notif = document.getElementById('cart-notification');
  const text  = document.getElementById('cart-notification-text');
  if (!notif || !text) return;
  text.textContent = `"${name}" added to your cart!`;
  notif.classList.add('show');
  notif.removeAttribute('aria-hidden');
  // Announce to screen readers
  notif.setAttribute('role', 'status');
  clearTimeout(notif._timeout);
  notif._timeout = setTimeout(() => closeCartNotification(), 4000);
}

function closeCartNotification() {
  const notif = document.getElementById('cart-notification');
  if (!notif) return;
  notif.classList.remove('show');
  notif.setAttribute('aria-hidden', 'true');
}

// ── Render functions ──────────────────────────────────
function renderCategories() {
  const el = document.getElementById('categories-grid');
  if (el) el.innerHTML = CATEGORIES.map(CategoryCard).join('');
}

function renderProducts(containerId) {
  const el = document.getElementById(containerId);
  if (el) el.innerHTML = PRODUCTS.map(ProductCard).join('');
}

function renderDeals() {
  const el = document.getElementById('deals-grid');
  if (el) el.innerHTML = DEALS.map(DealCard).join('');
}

function renderEditorial() {
  const el = document.getElementById('editorial-grid');
  if (el) el.innerHTML = EDITORIALS.map(EditorialCard).join('');
}

// ── Countdown Timer ───────────────────────────────────
function updateCountdown() {
  const remaining = Math.max(0, dealEndTime - Date.now());
  const h = Math.floor(remaining / 3_600_000);
  const m = Math.floor((remaining % 3_600_000) / 60_000);
  const s = Math.floor((remaining % 60_000) / 1_000);

  const pad = (n) => String(n).padStart(2, '0');
  const set = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = pad(val);
  };
  set('timer-h', h);
  set('timer-m', m);
  set('timer-s', s);
}

// ── Tabs ──────────────────────────────────────────────
function initTabs() {
  const btns   = document.querySelectorAll('.tab-btn');
  const panels = document.querySelectorAll('.tab-panel');

  btns.forEach((btn, i) => {
    btn.addEventListener('click', () => activateTab(i));
    btn.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowRight') { e.preventDefault(); activateTab((i + 1) % btns.length); btns[(i + 1) % btns.length].focus(); }
      if (e.key === 'ArrowLeft')  { e.preventDefault(); activateTab((i - 1 + btns.length) % btns.length); btns[(i - 1 + btns.length) % btns.length].focus(); }
      if (e.key === 'Home')       { e.preventDefault(); activateTab(0); btns[0].focus(); }
      if (e.key === 'End')        { e.preventDefault(); activateTab(btns.length - 1); btns[btns.length - 1].focus(); }
    });
  });

  function activateTab(index) {
    btns.forEach((b, i) => {
      const selected = i === index;
      b.setAttribute('aria-selected', String(selected));
      b.setAttribute('tabindex', selected ? '0' : '-1');
    });
    panels.forEach((p, i) => {
      p.classList.toggle('active', i === index);
      p.hidden = i !== index;
    });
    activeTab = index;
    // Re-render products for the active tab
    renderProducts(`products-grid-${index}`);
  }

  // Initialise
  activateTab(0);
}

// ── Cart interactions ─────────────────────────────────
function initCartInteractions() {
  // Delegate click events for cart & wishlist buttons
  document.addEventListener('click', (e) => {
    // Add to cart
    const cartBtn = e.target.closest('.add-to-cart-btn, .deal-btn');
    if (cartBtn) {
      const id = parseInt(cartBtn.dataset.id || cartBtn.dataset.dealId, 10);
      const product = PRODUCTS.find(p => p.id === id) || DEALS.find(d => d.id === id);
      cartCount++;
      updateCartBadge();
      if (product) showCartNotification(product.name);
      return;
    }

    // Wishlist toggle
    const wishBtn = e.target.closest('.wishlist-btn');
    if (wishBtn) {
      const id = parseInt(wishBtn.dataset.id, 10);
      const product = PRODUCTS.find(p => p.id === id);
      if (!product) return;
      if (wishlist.has(id)) {
        wishlist.delete(id);
        wishBtn.setAttribute('aria-pressed', 'false');
        wishBtn.setAttribute('aria-label', `Add to wishlist: ${product.name}`);
        wishBtn.innerHTML = heartIcon(false);
      } else {
        wishlist.add(id);
        wishBtn.setAttribute('aria-pressed', 'true');
        wishBtn.setAttribute('aria-label', `Remove from wishlist: ${product.name}`);
        wishBtn.innerHTML = heartIcon(true);
      }
      return;
    }

    // Close notification
    if (e.target.closest('#cart-notification-close')) {
      closeCartNotification();
    }
  });
}

function updateCartBadge() {
  const badge = document.getElementById('cart-badge');
  if (!badge) return;
  badge.textContent = cartCount;
  badge.setAttribute('aria-label', `${cartCount} item${cartCount !== 1 ? 's' : ''} in cart`);
  if (cartCount > 0) {
    badge.removeAttribute('hidden');
  }
}

// ── Mobile menu ───────────────────────────────────────
function initMobileMenu() {
  const toggle = document.getElementById('menu-toggle');
  const nav    = document.getElementById('primary-nav');
  const closeBtn = document.getElementById('menu-close');
  if (!toggle || !nav) return;

  function openMenu() {
    nav.classList.add('open');
    nav.removeAttribute('hidden');
    toggle.setAttribute('aria-expanded', 'true');
    document.body.style.overflow = 'hidden';
    closeBtn && closeBtn.focus();
  }
  function closeMenu() {
    nav.classList.remove('open');
    toggle.setAttribute('aria-expanded', 'false');
    document.body.style.overflow = '';
    toggle.focus();
  }

  toggle.addEventListener('click', openMenu);
  closeBtn && closeBtn.addEventListener('click', closeMenu);

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && nav.classList.contains('open')) closeMenu();
  });

  // Close when a nav link is clicked
  nav.querySelectorAll('.nav-link').forEach(link => {
    link.addEventListener('click', closeMenu);
  });
}

// ── Newsletter ────────────────────────────────────────
function initNewsletter() {
  const form    = document.getElementById('newsletter-form');
  const status  = document.getElementById('newsletter-status');
  if (!form || !status) return;

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const email = form.querySelector('input[type="email"]').value.trim();
    if (!email) return;

    status.textContent = '🎉 Thanks for subscribing! Check your inbox for a 10% discount code.';
    status.removeAttribute('hidden');
    status.setAttribute('role', 'status');
    form.reset();
  });
}

// ── Init ──────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  renderCategories();
  renderDeals();
  renderEditorial();
  initTabs();
  initCartInteractions();
  initMobileMenu();
  initNewsletter();
  updateCountdown();
  setInterval(updateCountdown, 1000);
  updateCartBadge();
});
